import {
	createEffect,
	createMemo,
	createSignal,
	JSX,
	mergeProps,
	on,
	onCleanup,
	ParentComponent,
	Show,
	splitProps,
} from "solid-js";
import { Portal } from "solid-js/web";

import { PropsRef } from "#core/ui-next/utilities/solid-utilities.js";

const DEFAULT_OFFSET: float3 = { x: 0, y: 0, z: 0 };

export interface WorldAnchorProps extends Omit<JSX.HTMLAttributes<HTMLDivElement>, "ref"> {
	/** The plot coordinate to anchor to. */
	location: PlotCoord;
	/** A 3d pixel offset above the anchor location. Default: `{ x: 0, y: 0, z: 0 }` */
	offset?: float3;
	/** How the anchor should be placed relative to terrain/water. Default: `PlacementMode.TERRAIN` */
	placement?: PlacementMode;

	ref?: PropsRef<HTMLDivElement>;

	/** Passes through to the portal */
	mount?: Node | string;
}

/**
 * Wraps its children in an element that is positioned in screen space to follow a fixed
 * plot location in the 3d world.
 */
export const WorldAnchor: ParentComponent<WorldAnchorProps> = (props) => {
	const mount = createMemo(() => {
		if (typeof props.mount === "string") {
			return document.querySelector(props.mount) ?? undefined;
		}
		return props.mount;
	});

	const merged = mergeProps({ offset: DEFAULT_OFFSET, placement: PlacementMode.TERRAIN }, props);
	const [local, other] = splitProps(merged, ["location", "offset", "placement", "children", "ref", "mount"]);

	const [handle, setHandle] = createSignal<number | null>(null);

	function unregisterAnchor() {
		const currentHandle = handle();
		if (currentHandle !== null) {
			WorldAnchors.UnregisterFixedWorldAnchor(currentHandle);
			setHandle(null);
		}
	}

	function registerAnchor() {
		const newHandle = WorldAnchors.RegisterFixedWorldAnchor(local.location, local.offset, local.placement);
		if (newHandle === null || newHandle < 0) {
			console.error("WorldAnchor: failed to register world anchor for location", local.location);
			setHandle(null);
			return;
		}

		setHandle(newHandle);
	}

	createEffect(
		on(
			() => {
				return [local.location, local.offset, local.placement] as const;
			},
			() => {
				registerAnchor();
				onCleanup(() => unregisterAnchor());
			},
		),
	);

	const anchor = (
		<div
			{...other}
			ref={local.ref}
			data-bind-style-transform2d={
				handle() !== null ? `{{FixedWorldAnchors.offsetTransforms[${handle()}].value}}` : undefined
			}
			data-bind-style-opacity={handle() !== null ? `{{FixedWorldAnchors.visibleValues[${handle()}]}}` : undefined}
		>
			{local.children}
		</div>
	);

	return (
		<Show
			when={mount()}
			fallback={anchor}
		>
			{(currentMount) => <Portal mount={currentMount()}>{anchor}</Portal>}
		</Show>
	);
};
